package de.phil.fitness.backend.workout.repository;

import de.phil.fitness.backend.workout.model.WorkoutSet;
import org.springframework.data.jpa.repository.JpaRepository;

import java.util.Optional;
import java.util.UUID;

public interface WorkoutSetRepository extends JpaRepository<WorkoutSet, Long> {
    /**
     * Returns the set with the id the client generated for it, whichever workout it belongs to. The caller checks the
     * ownership through the set's workout.
     * @param clientId Id generated by the client when the set was first logged.
     * @return The set, empty if no set has this client id.
     */
    Optional<WorkoutSet> findByClientId(UUID clientId);
}
